import app from 'flarum/forum/app';
import Component from 'flarum/common/Component';
import Button from 'flarum/common/components/Button';
import Link from 'flarum/common/components/Link';
import humanTime from 'flarum/common/helpers/humanTime';
import huntUrl from '../utils/huntUrl';
import CollectableCanvas from './CollectableCanvas';
/**
 * A Completion on a profile: the finished Collectable, when, and in what place.
 */
export default class TrophyCard extends Component {
  showReward = false;
  view() {
    const completion = this.attrs.completion;
    const hunt = completion.hunt();
    if (!hunt) return null;
    const parts = (hunt.parts() || []).filter(Boolean).sort((a, b) => a.sort() - b.sort());
    const url = huntUrl(hunt.slug());
    const rewardHtml = hunt.rewardMessageHtml();
    return m("article", {
      className: "TrophyCard"
    }, m(CollectableCanvas, {
      hunt: hunt,
      parts: parts,
      complete: true
    }), m("h4", {
      className: "TrophyCard-title"
    }, url ? m(Link, {
      href: url
    }, hunt.title()) : hunt.title()), m("div", {
      className: "TrophyCard-meta"
    }, app.translator.trans('fof-scavenger-hunt.forum.trophies.finished', {
      position: completion.position()
    }), " \xB7", ' ', humanTime(completion.completedAt())), rewardHtml ? m("div", {
      className: "TrophyCard-reward"
    }, m(Button, {
      className: "Button Button--link",
      icon: "fas fa-gift",
      onclick: () => this.showReward = !this.showReward
    }, app.translator.trans('fof-scavenger-hunt.forum.trophies.show_reward')), this.showReward && m("div", {
      className: "CompletionSummary-rewardMessage"
    }, m.trust(rewardHtml))) : null);
  }
}
flarum.reg.add('fof-scavenger-hunt', 'forum/components/TrophyCard', TrophyCard);