import app from 'flarum/forum/app';
import UserPage from 'flarum/forum/components/UserPage';
import LoadingIndicator from 'flarum/common/components/LoadingIndicator';
import TrophyCard from './TrophyCard';
export default class TrophiesPage extends UserPage {
  completions = null;
  oninit(vnode) {
    super.oninit(vnode);
    this.loadUser(m.route.param('username'));
  }
  show(user) {
    super.show(user);
    this.completions = null;
    app.store.find('scavenger-hunt-completions', {
      filter: {
        user: user.id()
      },
      include: 'hunt,hunt.parts',
      sort: '-completedAt',
      page: {
        limit: 50
      }
    }).then(completions => {
      this.completions = completions;
      m.redraw();
    });
  }
  content() {
    if (!this.completions) {
      return m(LoadingIndicator, null);
    }
    return m("div", {
      className: "TrophiesPage"
    }, this.completions.length ? m("div", {
      className: "TrophiesPage-grid"
    }, this.completions.map(completion => m(TrophyCard, {
      completion: completion
    }))) : m("p", {
      className: "TrophiesPage-empty"
    }, app.translator.trans('fof-scavenger-hunt.forum.trophies.empty')));
  }
}
flarum.reg.add('fof-scavenger-hunt', 'forum/components/TrophiesPage', TrophiesPage);